import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"sync"
	"time"
)

func FastHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
}

func HeavyHandler(w http.ResponseWriter, r *http.Request) {
	// Тяжелая аллокация
	garbage := make([][]byte, 100)
	for i := range garbage {
		garbage[i] = make([]byte, 64*1024)
	}
	_ = garbage
	w.WriteHeader(http.StatusOK)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/fast", FastHandler)
	mux.HandleFunc("/heavy", HeavyHandler)
	srv := httptest.NewServer(mux)
	defer srv.Close()

	client := srv.Client()

	// 1. Замер /fast в идеальных условиях
	t1 := time.Now()
	for i := 0; i < 1000; i++ {
		resp, _ := client.Get(srv.URL + "/fast")
		_ = resp.Body.Close()
	}
	baseDur := time.Since(t1)

	// 2. Замер /fast при параллельной работе /heavy
	var wg sync.WaitGroup
	stop := make(chan bool)

	for g := 0; g < 4; g++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				default:
					resp, err := client.Get(srv.URL + "/heavy")
					if err == nil {
						_ = resp.Body.Close()
					}
				}
			}
		}()
	}

	time.Sleep(50 * time.Millisecond)
	t2 := time.Now()
	for i := 0; i < 1000; i++ {
		resp, _ := client.Get(srv.URL + "/fast")
		_ = resp.Body.Close()
	}
	loadedDur := time.Since(t2)
	close(stop)
	wg.Wait()

	fmt.Println("=== Эффект Noisy Neighbor на уровне рантайма Go ===")
	fmt.Printf("1000 запросов /fast (без фона):     %v\n", baseDur)
	fmt.Printf("1000 запросов /fast (под /heavy GC): %v\n", loadedDur)
	fmt.Printf("Замедление быстрого эндпоинта:       +%.1f%%\n",
		float64(loadedDur-baseDur)/float64(baseDur)*100)
}

package main

import "fmt"

type RuntimeObject struct {
	Addr       uintptr
	IsPointer  []bool // Битмап указателей структуры (heapBits)
	ChildAddrs []uintptr
	MarkBit    bool // gcmarkBits
}

type GCWorkBuffer struct {
	queue []uintptr
}

func (w *GCWorkBuffer) Put(addr uintptr) {
	w.queue = append(w.queue, addr)
}

func (w *GCWorkBuffer) TryGet() (uintptr, bool) {
	if len(w.queue) == 0 {
		return 0, false
	}
	addr := w.queue[0]
	w.queue = w.queue[1:]
	return addr, true
}

var heapMap = make(map[uintptr]*RuntimeObject)

// scanobject исследует поля объекта и красит дочерние объекты в серый
func scanobject(addr uintptr, gcw *GCWorkBuffer) {
	obj := heapMap[addr]
	fmt.Printf("scanobject(0x%x): исследование полей...\n", addr)

	for i, isPtr := range obj.IsPointer {
		if isPtr && i < len(obj.ChildAddrs) {
			childAddr := obj.ChildAddrs[i]
			childObj := heapMap[childAddr]
			if childObj != nil && !childObj.MarkBit {
				// greyobject: помечаем бит и кладем в серую очередь
				childObj.MarkBit = true
				gcw.Put(childAddr)
				fmt.Printf("  -> Найден дочерний указатель 0x%x: помечен Серым\n", childAddr)
			}
		}
	}
	// Объект addr теперь ЧЕРНЫЙ
	fmt.Printf("scanobject(0x%x): завершено -> объект стал ЧЕРНЫМ\n", addr)
}

// gcDrain извлекает серые объекты, пока буфер не опустеет
func gcDrain(gcw *GCWorkBuffer) {
	fmt.Println(">>> Старт gcDrain() <<<")
	for {
		addr, ok := gcw.TryGet()
		if !ok {
			break
		}
		scanobject(addr, gcw)
	}
	fmt.Println(">>> gcDrain() завершен: серая очередь пуста <<<")
}

func main() {
	// Инициализируем объекты
	heapMap[0x1000] = &RuntimeObject{Addr: 0x1000, IsPointer: []bool{true}, ChildAddrs: []uintptr{0x2000}}
	heapMap[0x2000] = &RuntimeObject{Addr: 0x2000, IsPointer: []bool{true}, ChildAddrs: []uintptr{0x3000}}
	heapMap[0x3000] = &RuntimeObject{Addr: 0x3000, IsPointer: []bool{false}}

	gcw := &GCWorkBuffer{}
	// Корень 0x1000 стал серым
	heapMap[0x1000].MarkBit = true
	gcw.Put(0x1000)

	gcDrain(gcw)
}

